/**
 * @payloadcms/typescript-plugin
 *
 * A TypeScript Language Service Plugin that provides IDE assistance for the
 * custom "component path" strings used throughout Payload CMS configurations.
 *
 * A Payload component reference can appear in two shapes:
 *
 *   String form:
 *     '/path/to/Component.tsx#ExportName'  — explicit named export
 *     '/path/to/Component.tsx'             — uses the default export
 *     '@/path/to/Component#ExportName'     — using a tsconfig path alias
 *
 *   Object form:
 *     { path: '/path/to/Component.tsx', exportName: 'ExportName' }
 *     { path: '/path/to/Component.tsx#ExportName' }
 *     { path: '/path/to/Dir#ExportName' }  — directory resolved to its index file
 *
 * These values live in fields typed as `PayloadComponent` / `CustomComponent`
 * (or the underlying `RawPayloadComponent` object type) in the Payload config
 * type declarations. The plugin uses the type checker to decide whether a given
 * string / object literal is one of those component references and, if so,
 * validates the referenced file and export on disk.
 */
import type * as tslib from 'typescript';
declare function pluginInit({ typescript: ts }: {
    typescript: typeof tslib;
}): {
    create: (info: tslib.server.PluginCreateInfo) => tslib.LanguageService;
};
export default pluginInit;
